mapper.select:
SELECT COALESCE(SUM(pt.missed_amount), 0)
FROM payment_transaction pt
JOIN user_card uc ON pt.user_card_id = uc.user_card_id
WHERE uc.user_id = #{userId}
AND DATE_FORMAT(pt.paid_at, '%Y-%m') = #{yearMonth}

SELECT DISTINCT cp.card_product_id, cp.card_name, cp.card_image_url, c.category_id, c.category_name, bs.value_type, bs.value_number AS discountRate, bs.point_currency_id, pc.krw_per_point, bt.min_prev_month_spend, bl.limit_value, bl.limit_basis FROM benefit_service bs JOIN service_category sc ON bs.service_id = sc.service_id JOIN category c ON sc.category_id = c.category_id JOIN card_product cp ON bs.card_product_id = cp.card_product_id LEFT JOIN point_currency pc ON bs.point_currency_id = pc.point_currency_id LEFT JOIN benefit_tier bt ON bt.service_id = bs.service_id LEFT JOIN benefit_limit bl ON bl.tier_id = bt.tier_id WHERE c.category_id IN
#{categoryId}
AND cp.card_product_id NOT IN ( SELECT card_product_id FROM user_card WHERE user_id = #{userId} )
